#!/usr/bin/env python3
"""Build a self-contained, anonymized decision-readiness dashboard."""
from pathlib import Path
import html, json, re

ROOT = Path(__file__).resolve().parents[1]
DATA = ROOT / "data"
OUT = ROOT
sources_doc = json.loads((DATA / "sources.json").read_text())
metrics = json.loads((DATA / "metrics.json").read_text())["rows"]
questions = json.loads((DATA / "questions.json").read_text())
suggestions = json.loads((DATA / "suggestions.json").read_text())
risks = json.loads((DATA / "risks.json").read_text())
sources = {s["id"]: s for s in sources_doc["sources"]}
E = html.escape

NAV = [("index.html", "Overview"), ("executive-summary.html", "Executive summary"),
       ("market.html", "Area evidence"), ("questions.html", "Questions & answers"),
       ("projection.html", "Projection framework"), ("risks.html", "Risks"),
       ("suggestions.html", "Suggestion review"), ("flagged.html", "Flagged for review"),
       ("sources.html", "Sources"), ("privacy.html", "Privacy"),
       ("verification.html", "Verification")]

for row in metrics + questions + suggestions + risks:
    for sid in [row["source"]] + row.get("also_sources", []):
        assert sid in sources, f"Missing source {sid} for {row.get('id')}"
for source in sources.values():
    assert source["url"].startswith("https://"), source["id"]
for row in metrics:
    assert row["status"] in {"verified", "unverified"}
    assert (row["value"].strip() != "") if row["status"] == "verified" else (row["value"] == "")

CSS = """*{box-sizing:border-box}body{margin:0;background:#f4f7fb;color:#14253d;font:16px/1.55 system-ui,-apple-system,Segoe UI,sans-serif}a{color:#1457a6}a:hover{color:#0d3568}.shell{max-width:1180px;margin:auto;padding:0 22px}.top{background:#10233f;color:white;border-bottom:4px solid #36c4b1}.bar{display:flex;gap:24px;align-items:center;justify-content:space-between;padding:18px 0}.brand{font-weight:750;color:white;text-decoration:none;font-size:1.05rem}.brand small{display:block;font-weight:400;color:#cfdae8;font-size:.78rem}.nav{display:flex;flex-wrap:wrap;gap:8px}.nav a{color:#e5eefb;text-decoration:none;padding:6px 9px;border-radius:7px;font-size:.86rem}.nav a:hover,.nav a[aria-current=page]{background:#244569;color:white}.main{padding:24px 0 50px}.kicker{color:#087f78;font-weight:750;text-transform:uppercase;letter-spacing:.09em;font-size:.76rem}.hero{background:linear-gradient(120deg,#10233f,#1a4167);color:#fff;padding:28px;border-radius:18px;margin:12px 0 22px}.hero h1{font-size:clamp(1.8rem,4vw,2.8rem);line-height:1.15;margin:.3em 0}.hero p{max-width:900px}.hero a{color:#a8ddff}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px;margin:18px 0}.card,.panel{background:#fff;border:1px solid #dbe3ee;border-radius:13px;padding:18px;box-shadow:0 2px 7px #18304c0a}.card strong{display:block;font-size:1.25rem}.card span{color:#52647c;font-size:.9rem}.panel{margin:16px 0}.notice{border-left:5px solid #dd9b27;background:#fff7e5;padding:15px 18px;border-radius:8px}.good{border-color:#19877a;background:#eaf8f5}.bad{border-color:#c85a46;background:#fff0ec}h1,h2,h3{line-height:1.2}h2{margin-top:1.5em}table{width:100%;border-collapse:collapse;background:white}th,td{text-align:left;vertical-align:top;padding:11px;border-bottom:1px solid #e0e7ef}th{background:#eaf0f7;color:#263b57;font-size:.88rem}tr:hover td{background:#f9fbfd}.tablewrap{overflow-x:auto;border:1px solid #dbe3ee;border-radius:10px;margin:12px 0}.badge{display:inline-block;padding:3px 8px;border-radius:99px;background:#eaf8f5;color:#08665e;font-size:.78rem;font-weight:700}.badge.warn{background:#fff2d5;color:#825500}.badge.critical{background:#ffe5df;color:#8e2c1a}.muted{color:#596a80}.small{font-size:.86rem}.button{border:1px solid #aebed0;background:#f3f7fb;color:#14395d;border-radius:7px;padding:6px 9px;margin:2px;cursor:pointer}.button[aria-pressed=true]{background:#d8f2eb;border-color:#1b8a77}.button.reject[aria-pressed=true]{background:#ffe6e0;border-color:#bd604e}.footer{background:#10233f;color:#d6e0eb;padding:22px 0}.footer a{color:#a9dcff}.footer p{margin:.3em 0}.callout{padding:16px 18px;background:#e8f4ff;border-radius:9px;border-left:5px solid #4487ba}.tag{font-size:.77rem;background:#edf2f8;padding:3px 7px;border-radius:5px}.skip{position:absolute;left:-10000px}.skip:focus{left:10px;background:white;padding:10px}.formrow{display:flex;gap:6px;flex-wrap:wrap}.status-cell{min-width:210px}@media(max-width:760px){.bar{align-items:flex-start;flex-direction:column}.nav{gap:3px}.nav a{font-size:.8rem}td,th{padding:8px;font-size:.9rem}.hero{padding:21px}}@media print{.top,.footer,.actions{display:none}body{background:white}.shell{max-width:none;padding:0}.card,.panel{box-shadow:none}}"""
(ROOT / "assets").mkdir(exist_ok=True)
(ROOT / "assets/style.css").write_text(CSS)


def link(sid, label=None):
    src = sources[sid]
    return f'<a href="{E(src["url"])}" target="_blank" rel="noopener noreferrer" aria-label="Official source: {E(src["publisher"])} — {E(src["title"])}">{E(label or (sid + " ↗"))}</a>'


def source_cell(row):
    ids=[row['source']]+row.get('also_sources',[])
    return ' · '.join(link(sid) for sid in ids)

def table(headers, rows):
    return '<div class="tablewrap"><table><thead><tr>' + ''.join(f'<th>{h}</th>' for h in headers) + '</tr></thead><tbody>' + ''.join('<tr>'+''.join(f'<td>{c}</td>' for c in row)+'</tr>' for row in rows) + '</tbody></table></div>'


def layout(filename, title, eyebrow, body):
    nav = ''.join(f'<a href="{u}"'+(' aria-current="page"' if u==filename else '')+f'>{label}</a>' for u,label in NAV)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="An anonymized decision-readiness dashboard for a central Los Angeles Jack in the Box NNN lease decision."><title>{E(title)} | Jack2 Decision Readiness</title><link rel="stylesheet" href="assets/style.css"></head><body><a class="skip" href="#main">Skip to content</a><header class="top"><div class="shell bar"><a class="brand" href="index.html">Jack2 · Decision Readiness<small>Central Los Angeles · anonymized · evidence-led</small></a><nav class="nav" aria-label="Main navigation">{nav}</nav></div></header><main class="shell main" id="main"><p class="kicker">{eyebrow}</p>{body}</main><footer class="footer"><div class="shell"><p><strong>Internal decision support only.</strong> Not an appraisal, legal opinion, tax advice, or investment advice.</p><p>Privacy rule: no owner, street-address, APN, tenant-contact, account, or taxpayer-identifying information is published. Unknown property facts remain blank.</p><p>Official-source access date for this dashboard: {sources_doc['access_date']}. The cited public data do not identify or value the subject parcel.</p></div></footer></body></html>'''


# Overview
body = f'''<section class="hero"><p class="kicker" style="color:#8ee8d9">Executive decision brief</p><h1>Do not make an irreversible sell-or-renew decision from area averages.</h1><p>Best current course: preserve both choices. Abstract the actual lease, obtain a tenant extension proposal and independent sale pricing in parallel, then choose only after comparing risk-adjusted after-tax net outcomes. The exact site, lease terms, NOI, tax basis, debt, insurance, and sale offers are not available; the property-specific answer is therefore <strong>not yet knowable</strong>.</p><p><a href="executive-summary.html">Read the full executive summary →</a> &nbsp; <a href="questions.html">See required answers →</a></p></section>
<div class="grid"><div class="card"><span>Published area evidence</span><strong>9 linked observations</strong><span>City/county and metro proxies only</span></div><div class="card"><span>Unverified / withheld rows</span><strong>7 blank</strong><span>Not inferred or simulated</span></div><div class="card"><span>Decision questions</span><strong>{len(questions)}</strong><span>Prioritized; required documents listed</span></div><div class="card"><span>Risk register</span><strong>{len(risks)}</strong><span>BAU + rare/severe, each linked</span></div></div>
<div class="notice"><strong>Critical limitation.</strong> “Central Los Angeles” is not a verified parcel or trade area. County/city/metro numbers below cannot establish neighborhood demand, school assignment, zoning, hazard exposure, insurance, market value, or lease economics.</div>
<h2>What official area evidence says — and does not say</h2>
{table(['Indicator','Published observation','Interpretation','Source'], [[E(r['topic'])+' · '+E(r['geography']),E(r['value']),E(r['meaning']),source_cell(r)] for r in metrics if r['status']=='verified'])}
<h2>Decision gate</h2><div class="panel"><ol><li><strong>Protect the option clock:</strong> have counsel confirm actual expiry, options, notice periods, and obligations.</li><li><strong>Underwrite the asset:</strong> verify rent/NOI, lease allocations, repair condition, tax basis, debt and insurance privately.</li><li><strong>Run both paths:</strong> obtain a written extension offer and independently supported sale range; calculate net proceeds and risk-adjusted cash flows.</li><li><strong>Decide at a documented hurdle:</strong> extend only if its risk-adjusted after-tax value exceeds sale/reinvestment and meets liquidity/diversification needs; sell only if net offers clear the same hurdle and a viable reinvestment plan exists.</li></ol><p>Until steps 1–3 are complete, neither “sell now” nor “renew” is supported by the verified evidence.</p></div>
<h2>Explore the decision workspace</h2><div class="grid"><div class="card"><strong><a href="market.html">Area evidence</a></strong><span>Geography, population, income, jobs, education and explicit scale limits.</span></div><div class="card"><strong><a href="questions.html">Questions & answers</a></strong><span>What is known, unknown, why it matters, and what evidence to obtain.</span></div><div class="card"><strong><a href="suggestions.html">Suggestion review</a></strong><span>Review, accept, defer or reject proposed improvements; choices stay in this browser.</span></div><div class="card"><strong><a href="flagged.html">Flagged for review</a></strong><span>Unverified inputs and repository irregularities requiring human professional review.</span></div></div>'''
(OUT/'index.html').write_text(layout('index.html','Overview','Decision dashboard',body))

# Executive summary
body = '''<h1>Executive summary</h1><div class="notice good"><strong>Recommended next move: preserve optionality, not a forced binary.</strong> Start a dual-track process: verify lease milestones and property economics, invite a written extension proposal, and get independent sale pricing at the same time. Make no commitment until after-tax net values and downside risks are comparable.</div>
<h2>Current facts and limits</h2><ul><li>User-described asset: Jack in the Box property, NNN lease, central Los Angeles, lease expiration somewhere in 2030–2035. This is user-supplied context, not independently verified property documentation.</li><li>Official city/county 2025 Census population estimates and 2020–2024 ACS income/education measures are available, as are preliminary September 2026 metro jobs and unemployment measures. They are broad proxies, not a specific customer area.</li><li>No exact parcel, property rent, NOI, actual option/notice rights, tenant guarantor, sale offer/appraisal, debt, basis, tax estimate, insurance quote, physical-condition report, or replacement investment was provided. Each remains blank.</li><li>Therefore there is no source-supported property valuation, property forecast, tax comparison, cap rate, or quantitative sell/renew winner in this dashboard.</li></ul>
<h2>Best decision framework</h2><p>Evaluate sell now / sell later, extension then hold, extension then sale, and hold to expiry under common assumptions. Compare after-tax cash flows, sale friction, lease income and residual value, tenant-default/vacancy, capital needs, insurance, liquidity, concentration and reinvestment execution. Optimize for the owner's stated goals—wealth preservation, growth, and manageable risk—not a single headline return.</p><p>A renewal should be selected only if the documented extension terms and downside-adjusted hold value beat credible net sale-and-reinvestment alternatives while satisfying liquidity and concentration limits. A sale should be selected only if defensible net bids beat the hold/extension alternative and the post-sale plan is executable. No numeric hurdle is set because required private inputs and risk preferences are unknown.</p>
<h2>Suggested sequence</h2><ol><li>Privately assemble the executed lease, amendments, option/notice calendar, title/parcel, rent ledger, expense history, tax basis, debt/payoff, insurance and inspection materials.</li><li>Have counsel/CPA verify legal and tax issues; keep personal information in private professional records only.</li><li>Obtain written renewal terms and independent sale valuations/offers in parallel; test comparable lease term, rent, tenant credit and property condition.</li><li>Complete parcel-specific demand, land-use, school-boundary, hazard and insurance review only after location is privately verified.</li><li>Run bear/base/upside and severe-event cases; document assumptions, confidence ranges, break-even points and chosen risk limits.</li><li>Revisit each quarter and before each confirmed lease notice milestone; update official data vintages and market evidence.</li></ol>
<h2>What could alter the recommendation?</h2><p>A very attractive firm extension, poor net sale bids, an adverse tax/transaction result, significant uninsured loss exposure, weak tenant credit, a major physical defect, local redevelopment constraints, or strong alternative use/value could each change the best path. See the <a href="questions.html">decision questions</a>, <a href="risks.html">risk register</a>, and <a href="suggestions.html">suggestion review</a>.</p>
<p class="small muted">All claims about public statistics link to official publishers on the Area Evidence page. This is a structured decision aid, not individualized legal, tax, appraisal, insurance, or investment advice.</p>'''
(OUT/'executive-summary.html').write_text(layout('executive-summary.html','Executive summary','Decision brief',body))

# Area evidence
body = '''<h1>Area evidence and geographic limits</h1><p>Only official-source values directly read from the named publisher are populated. The city, county, and metropolitan statistical area are not interchangeable; none is a confirmed site trade area. Values are observations, not forecasts.</p>'''
body += table(['ID / topic','Geography and period','Value','How to interpret it','Official source'], [[E(r['id'])+' · '+E(r['topic']),E(r['geography'])+' · '+E(r['period']),E(r['value']),E(r['meaning']),source_cell(r)] for r in metrics])
body += '''<h2>Why the geography matters</h2><ul><li><strong>Population, income, poverty, education:</strong> Census QuickFacts observations are city/county-wide and hide neighborhood variation. Use tract/block-group data or a defensible trade area only after the parcel is privately verified; include ACS margins of error and vintages.</li><li><strong>Jobs:</strong> BLS metro data aggregate a large multi-city area. The published +0.5% total payroll job change for September 2025–September 2026 is explicitly not statistically significant at 90% confidence; the latest estimate is preliminary.</li><li><strong>Schools:</strong> citywide education attainment is not school system quality. First verify attendance boundaries, then use current school-specific California Dashboard outcomes and enrollment—not a guessed school.</li><li><strong>Geography, access and economic activity:</strong> trade-area population, traffic counts, daytime workers, competition, planned development and retailer/store performance remain unverified. Do not convert regional indicators into a property value or rent forecast.</li></ul><h2>Official source pages</h2><p>See the full <a href="sources.html">source register</a>, including Census, BLS, California Department of Education, City Planning, Assessor, FEMA, CAL FIRE, USGS and IRS primary links.</p>'''
(OUT/'market.html').write_text(layout('market.html','Area evidence','Market and geography',body))

# Questions and answers
qrows=[]
for r in questions:
    qrows.append([E(r['id'])+' · '+E(r['category'])+'<br><span class="badge '+('critical' if r['priority']=='Critical' else 'warn')+'">'+E(r['priority'])+'</span>',E(r['question']),E(r['answer']),E(r['needed']),E(r['decision_impact']),source_cell(r)])
body='<h1>Questions & answers before any decision</h1><p>Every question below is answered only to the level supported by existing verified information. “Unknown” is deliberate—not an invitation to infer. The official link identifies the relevant record, dataset, or governing guidance; it does not independently prove private lease or taxpayer facts.</p>'+table(['ID / category','Question','Answer now','Evidence to obtain','Why it matters','Official context'],qrows)
body+='<div class="notice"><strong>Confidential handling:</strong> provide sensitive documents only to authorized counsel, CPA, broker, lender or insurer. Keep all owner/parcel identifiers outside the public website. The dashboard does not require the owner to enter anything.</div>'
(OUT/'questions.html').write_text(layout('questions.html','Questions & answers','Pre-decision diligence',body))

# Projection framework
body='''<h1>Projection framework—not a fabricated forecast</h1><div class="notice"><strong>No property-specific forecast is publishable yet.</strong> The asset's NOI, sale value, tax basis, lease dates, hazard, insurance and investor-specific constraints are missing. We do not fill them with generic cap rates, location guesses, or placeholder returns.</div><p>Once the required inputs are verified, build a reproducible annual after-tax cash-flow model from the present through at least the confirmed lease expiry and a common post-expiry horizon. Every input must carry source, date, geography, unit, confidence/status and whether observed or assumed.</p>
<h2>Required model branches</h2>'''
body += table(['Scenario','Must include','Decision question','Official context'],[
 ['Sell now / market sale','Verified offer range; transaction costs; taxes; debt payoff; closing timing; replacement allocation and return/fee/liquidity range.','What is the actual net proceeds floor and credible replacement opportunity?',link('IRS1')],
 ['Operate to lease expiry, then sell','Contract rent/bumps, expenses landlord retains, repairs/capex, tenant performance, vacancy risk, terminal value and selling friction.','Is interim income worth carrying tenant, asset and market risk?',link('ASSR1')],
 ['Extend, then hold','Written extension terms; escalations/options; repairs and insurance; credit, vacancy, disaster and terminal value.','Does extension rent compensate for capital, concentration and tail risks?',link('IRS1')],
 ['Extend, then sell','Extension economics plus buyer pricing under the longer lease and its restrictions.','Does extension improve buyer demand or lock value below alternative use?',link('IRS1')],
 ['Default / vacancy / severe event','Tenant failure, reletting delay and cost; earthquake/wildfire/flood damage; business interruption, coverage limits, deductibles and access disruption.','Can owner absorb tail losses without forced sale or wealth-damaging liquidity stress?',' · '.join(link(s) for s in ['FEMA1','FIRE1','USGS1'])]])
body+='''<h2>Model architecture</h2><ol><li>Use lease-derived rent and verified owner expense/capital obligations; independently reconcile cash receipts and tax/assessor records.</li><li>Use sale comparables only after matching asset type, lease term, rent, tenant credit, location and date. Report a range; market cap rates are transaction evidence, not official statistics.</li><li>Separate operating cash flow, land/building residual value, sale friction, debt repayment, taxes, and reinvestment. Tax and Section 1031 outcomes require individualized professional advice.</li><li>Scenarios: bear/base/upside for macro, local demand, rent growth, exit yield, expenses, rates and liquidity; severe but plausible shocks for tenant failure, earthquake, wildfire/smoke, flood/utility disruption and insurance nonrenewal.</li><li>Use sensitivity/tornado analysis and break-even conditions first. Monte Carlo is optional only where distributions are evidence-based; do not call an assumed probability a forecast.</li><li>Report median and downside percentiles, probability of shortfall against a privately selected wealth/liquidity floor, and model limitations. Never report false precision.</li></ol><h2>Public signal currently available</h2><p>Official Census and BLS observations appear on <a href="market.html">Area Evidence</a>. They support context only: they do not predict site sales, Jack in the Box revenue, property rent, cap rates, or value. School, zoning, trade-area and parcel hazards remain open questions until location is verified.</p>'''
(OUT/'projection.html').write_text(layout('projection.html','Projection framework','Scenario design',body))

# risks
riskrows=[[E(r['id'])+' · '+E(r['decision']),'<span class="tag">'+E(r['class'])+'</span>',E(r['risk']),E(r['mitigation']),E(r['trigger']),source_cell(r)] for r in risks]
body='<h1>Risk register: every path has downside</h1><p>Risk statements are pathways to investigate, not claims that an event has occurred or a quantified probability. Regional hazards cannot establish property-specific exposure. Every row has an official-source context link.</p>'+table(['ID / path','Event class','Risk','Mitigation / diligence','Decision trigger','Source'],riskrows)
body+='<h2>Risk balance</h2><p>Renewal retains tenant credit, lease, physical asset, local-market and catastrophe exposure. Sale removes direct property and tenant exposure but creates transaction/tax friction, reinvestment risk, and possible loss of upside. Waiting preserves options but concentrates risk and can miss contract deadlines. Set tolerances for liquidity, concentration, uninsured loss and expected downside before comparing paths; these personal risk settings should remain private.</p>'
(OUT/'risks.html').write_text(layout('risks.html','Risk register','Business-as-usual and severe risks',body))

# suggestions with local-only review
srows=[]
for r in suggestions:
    actions=f'''<span class="actions formrow" data-id="{E(r['id'])}"><button class="button" data-choice="accept">Accept for review</button><button class="button" data-choice="defer">Defer</button><button class="button reject" data-choice="reject">Reject</button></span><span class="small review-state" aria-live="polite">Not reviewed in this browser</span>'''
    srows.append([E(r['id']),E(r['priority']),'<strong>'+E(r['title'])+'</strong><br>'+E(r['proposal']),E(r['why']),'<span class="badge">'+E(r['status'])+'</span><br>'+E(r['review']),actions,source_cell(r)])
body='<h1>Suggestion review: select a path before implementation</h1><div class="notice"><strong>Review only.</strong> Suggestions are proposals, not implemented business or property changes. Select Accept for review, Defer, or Reject; selections are stored only in this browser via local storage, not transmitted to a server. This UI does not change property decisions or source data.</div><p>Recommended order: protect private information → verify lease/property facts → parallel market sounding → parcel-scale underwriting → risk-adjusted decision. No owner input is required for this research deliverable.</p>'+table(['ID','Priority','Proposed change','Decision benefit','Current status','Your local review choice','Source'],srows)
body+='''<h2>Review states are not approval to act</h2><p>“Accept for review” means put the suggestion on an internal shortlist for a human/professional assessment. It does not authorize outreach, a property transaction, disclosure of data, or implementation. Clear local selections by clearing this browser's site data.</p><script>document.querySelectorAll('[data-id]').forEach(group=>{const id=group.dataset.id,key='jack2-review-'+id,state=group.parentElement.querySelector('.review-state');const saved=localStorage.getItem(key);if(saved){state.textContent='Your local selection: '+saved;group.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.choice===saved)));}group.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{localStorage.setItem(key,b.dataset.choice);state.textContent='Your local selection: '+b.dataset.choice;group.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));}));});</script>'''
(OUT/'suggestions.html').write_text(layout('suggestions.html','Suggestion review','Recommendations queue',body))

# flagged page
flagrows=[]
for r in metrics:
    if r['status']!='verified': flagrows.append([E(r['id']),E(r['topic']),E(r['geography']),'<strong>Blank — unverified</strong><br>'+E(r['meaning']),source_cell(r)])
body='<h1>Flagged for review</h1><p>Values and conclusions are deliberately withheld where evidence is not sufficient. Review the needed evidence and official source context; do not treat blanks as zero or “no risk.”</p>'+table(['Flag / topic','Geography','Status / issue','What is missing or irregular','Official source context'],flagrows)
body+='<div class="notice"><strong>Repository-specific irregularities:</strong><ul><li>The root README still names the November 10 Session M workbook as the current starting point although the shared workspace index records later workbooks. Review the README pointer against <a href="../workspaces.html">All workspaces</a>.</li><li>This repository contains overlapping historic workbooks with different assumptions, dates, models, and recommendation rankings. Their recorded verification claims are not independently re-established by this dashboard; treat property-specific numbers as unverified until inputs and source vintages are checked.</li></ul>See this dashboard’s <a href="verification.html">verification limits</a> and <a href="questions.html">required evidence checklist</a>.</div>'
(OUT/'flagged.html').write_text(layout('flagged.html','Flagged for review','Open items and irregularities',body))

# Sources page
srows=[[E(s['id']),E(s['publisher']),E(s['title']),link(s['id'],'Open official source ↗'),E(s['use'])] for s in sources_doc['sources']]
body=f'<h1>Official source register</h1><p>Publisher pages were opened and relevant facts checked on {E(sources_doc["access_date"])}. Source links provide independent manual review. Sources identify what can be researched; they do not prove unknown private property facts.</p>'+table(['ID','Official publisher','Source title','Link','Use and limits'],srows)
body+='<p class="small muted">No commercial listing, broker opinion, model output, secondary news report, or uncited previous workbook is presented as verified official evidence.</p>'
(OUT/'sources.html').write_text(layout('sources.html','Source register','Primary sources',body))

# privacy
body='''<h1>Privacy is a hard requirement</h1><div class="notice good"><strong>Public-site rule:</strong> never publish personally identifying, parcel-identifying, tenant-contact, taxpayer, banking, or authentication information.</div><h2>Not published and not requested here</h2><ul><li>Owner names, personal addresses, emails, phone numbers, signatures or contact details.</li><li>Property street address, APN, legal description, parcel map, access credentials, or combinations that uniquely identify a private owner/property.</li><li>Tax returns, basis, debt/account numbers, bank information, insurance policy identifiers, unredacted lease documents, tenant contacts, or personally attributable wealth information.</li></ul><h2>Use placeholders and minimum necessary data</h2><p>Use a random non-identifying asset key for private professional workflows. For public reporting, publish only properly aggregated or rounded information after a disclosure review. Keep source documents in access-controlled systems managed by counsel/CPA/advisors, never in GitHub Pages or this repository.</p><h2>Browser suggestion controls</h2><p>Suggestion-review selections are stored only in local browser storage. No decision, identity, or private document is submitted to the site. Avoid using public/shared devices for sensitive decision work.</p><h2>Privacy limitation</h2><p>Repository history and static hosting can preserve old content. If any personal information is discovered in existing repository material, it must be treated as a release-blocking incident: stop publication, request authorized removal from current and historical copies, and review repository and hosting history. This dashboard itself contains no owner or parcel identifiers.</p>'''
(OUT/'privacy.html').write_text(layout('privacy.html','Privacy','Privacy safeguards',body))

# verification report
tests=[
 ('Every data record has an existing official-source id', all(r['source'] in sources for r in metrics+questions+suggestions+risks)),
 ('All official source URLs use HTTPS', all(s['url'].startswith('https://') for s in sources.values())),
 ('Verified metric rows have values and unverified rows are blank', all((r['value'].strip()!='') if r['status']=='verified' else r['value']=='' for r in metrics)),
 ('No APN, contact email, phone, or street-address pattern in generated files', None),
 ('Every generated local navigation target exists', None),
 ('One official external source link per metric, question, suggestion and risk row', all(r['source'] in sources for r in metrics+questions+suggestions+risks)),
]
# Scan all generated HTML plus JSON for common identifiers; property values are placeholders by design.
content='\n'.join(p.read_text(errors='ignore') for p in OUT.glob('*.html'))+'\n'+ '\n'.join(p.read_text() for p in DATA.glob('*.json'))
patterns=[r'\bAPN\s*[:#]?\s*\d{4,}',r'[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}',r'\(?\d{3}\)?[ .-]\d{3}[ .-]\d{4}',r'\b\d{1,6}\s+(?:[A-Z][a-z]+\s+){1,3}(?:Street|St|Avenue|Ave|Boulevard|Blvd|Road|Rd|Drive|Dr)\b']
pii=not any(re.search(p,content) for p in patterns)
local_ok=all((OUT/u).exists() for u,_ in NAV if u != 'verification.html') and any(u == 'verification.html' for u,_ in NAV)
tests[3]=(tests[3][0],pii); tests[4]=(tests[4][0],local_ok)
result={'access_date':sources_doc['access_date'],'pages':len(NAV),'metrics':len(metrics),'verified_metrics':sum(r['status']=='verified' for r in metrics),'blank_unverified_metrics':sum(r['status']!='verified' for r in metrics),'questions':len(questions),'suggestions':len(suggestions),'risks':len(risks),'checks':[{'name':n,'pass':bool(ok)} for n,ok in tests]}
(OUT/'verification.json').write_text(json.dumps(result,indent=2)+'\n')
(OUT/'verification.html').write_text(layout('verification.html','Verification','Build and evidence checks','<h1>Verification log</h1><p>Automated checks enforce source completeness, blank unknowns, common PII patterns, and local page presence. These checks do not replace review of source meaning or completeness.</p><ul>'+''.join(f'<li><span class="badge">{("PASS" if ok else "FAIL")}</span> {E(n)}</li>' for n,ok in tests)+'</ul>'+f'<p>Built {result["pages"]} pages; {result["verified_metrics"]}/{result["metrics"]} metrics verified, {result["blank_unverified_metrics"]} deliberately blank; {result["questions"]} questions; {result["suggestions"]} suggestions; {result["risks"]} risks.</p><p><a href="verification.json">Machine-readable verification summary</a></p>'))
if not all(ok for _,ok in tests):
    raise SystemExit('verification failed')
print(f"Built {result['pages']} pages; {result['verified_metrics']}/{result['metrics']} metrics verified; {result['questions']} questions; {result['risks']} risks; all checks pass.")
